import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Utilizzo del \\"numero\\" pi greco","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fr/frf.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fr/frf.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fr/frf.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="utilizzo-del-numero-pi-greco" tabindex="-1">Utilizzo del &quot;numero&quot; pi greco <a class="header-anchor" href="#utilizzo-del-numero-pi-greco" aria-label="Permalink to “Utilizzo del &quot;numero&quot; pi greco”">​</a></h1><p><strong>Pi greco</strong> è un numero reale e non razionale;</p><p>È possibile, misurando il perimetro dei poligoni inscritti e circoscritti, come fatto nelle pagine precedenti, determinare in modo più preciso il valore di pi greco (esempio: Archimede nell&#39;opera &quot;Misura del cerchio&quot;) ma, geometricamente, è quasi impossibile superare la seconda cifra decimale: bisognerà utilizzare le serie di potenze per avere la determinazione del valore di pi greco fino alla cifra decimale voluta (fare link quando sviluppo)</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mi>π</mi><mo>=</mo><mn>3</mn><mo separator="true">,</mo><mn>141592654...</mn></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\pi = 3,141592654...} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;color:red;">π</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord" style="color:red;">3</span><span class="mpunct" style="color:red;">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord" style="color:red;">141592654...</span></span></span></span></span></p><p>Di solito, nei problemi scolastici di misura, nella scuola media inferiore, si approssima alla seconda cifra decimale</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mi>π</mi><mo>≈</mo><mn>3</mn><mo separator="true">,</mo><mn>14</mn></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\pi \\approx 3,14} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4831em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;color:red;">π</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord" style="color:red;">3</span><span class="mpunct" style="color:red;">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord" style="color:red;">14</span></span></span></span></span></p><blockquote><p><strong>NOTA IMPORTANTE</strong></p><p>Quando risolvi un problema di matematica in modo esatto non puoi sostituire al valore di <strong>pi greco</strong> un numero, per quanti decimali esso abbia: il numero <strong>pi greco</strong> (trascendente) è un decimale illimitato e non periodico.</p><p>Quindi, per poter risolvere un problema in modo matematico, dovrai sempre mantenere il simbolo <strong>pi greco</strong> (naturalmente ricordando che vale circa <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn><mo separator="true">,</mo><mn>14</mn></mrow><annotation encoding="application/x-tex">3,14</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">3</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">14</span></span></span></span>). Ad esempio:</p><p><strong>Problema</strong> Trovare la lunghezza della circonferenza di raggio <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi><mo>=</mo><mn>5</mn><mtext>\xA0cm</mtext></mrow><annotation encoding="application/x-tex">r = 5 \\text{ cm}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">5</span><span class="mord text"><span class="mord">\xA0cm</span></span></span></span></span></p><p><strong>Soluzione</strong></p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Circonferenza</mtext><mo>=</mo><mn>2</mn><mi>π</mi><mi>r</mi><mo>=</mo><mn>2</mn><mi>π</mi><mo>⋅</mo><mn>5</mn><mo>=</mo><mn>10</mn><mi>π</mi><mtext>\xA0cm</mtext></mrow><annotation encoding="application/x-tex">\\text{Circonferenza} = 2\\pi r = 2\\pi \\cdot 5 = 10\\pi \\text{ cm} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">Circonferenza</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">10</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mord text"><span class="mord">\xA0cm</span></span></span></span></span></span></p><p>Questo è il valore matematico della lunghezza della circonferenza. Il fatto che valga all&#39;incirca <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>31</mn><mo separator="true">,</mo><mn>4</mn><mtext>\xA0cm</mtext></mrow><annotation encoding="application/x-tex">31,4 \\text{ cm}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">31</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">4</span><span class="mord text"><span class="mord">\xA0cm</span></span></span></span></span> (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10</mn><mo>⋅</mo><mn>3</mn><mo separator="true">,</mo><mn>14...</mn></mrow><annotation encoding="application/x-tex">10 \\cdot 3,14...</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">10</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">3</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">14...</span></span></span></span>) ti deve essere noto, ma non deve essere scritto nello svolgimento del problema.</p></blockquote>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};